// src/motor/paket.ts
function belgeIcerigi(b2, d) {
  const t = turet(d);
  if (b2.tur === "yaml") return `# Tasar\u0131m: uygulanmad\u0131; \xE7al\u0131\u015Ft\u0131r\u0131labilir motor konfig\xFCrasyonu de\u011Fildir.
# Senaryo: ${t.senaryo.ad}
` + JSON.stringify({ schema: "scenario-policy/draft-v1", lifecycle_owner: d.kararlar.durumSahibi, worker: d.kararlar.ajan, decision_engine: d.kararlar.kararModeli, eca: d.kurallar, unknown_effect: "reconcile_before_retry", real_system_qualification: "not_run" }, null, 2) + "\n";
  if (b2.tur === "di\u011Fer") return "# Tasar\u0131m tasla\u011F\u0131: " + t.senaryo.ad + "\n" + b2.sablon;
  return `# Tasar\u0131m ba\u011Flam\u0131

Senaryo: ${t.senaryo.ad}
Ya\u015Fam d\xF6ng\xFCs\xFC sahibi: ${d.kararlar.durumSahibi}
Kodlama \xE7al\u0131\u015Fan\u0131: ${d.kararlar.ajan}
Tipli karar aday\u0131: ${d.kararlar.kararModeli}
Hedef: Plane \u2192 agentic-tdd-development \u2192 GitHub CI/CD \u2192 alpha \u2192 insan
Durum: taslak; uygulanmad\u0131. S\xFCr\xFCm ve endpoint alanlar\u0131 nitelendirme s\u0131ras\u0131nda doldurulacak.

---

${b2.sablon}

## Bu karara ba\u011Fl\u0131 ECA se\xE7imi
${KURALLAR.map((k) => `- ${k.id} [${d.kurallar[k.id].acik ? "se\xE7ili" : "kapal\u0131"}] ${k.baslik}`).join("\n")}
`;
}
function paket(d) {
  const t = turet(d);
  return {
    format: "senaryo-atlasi/karar-paketi",
    surum: 1,
    uretildi: (/* @__PURE__ */ new Date()).toISOString(),
    durum: d,
    sinir: "Tasar\u0131m ve yerel sim\xFClasyon. Kurulum yap\u0131lmad\u0131; ger\xE7ek sistem uygunlu\u011Fu kan\u0131tlanmad\u0131.",
    bulguNotlari: notlariOku(),
    kararDestegi: bulgular_default.briefs,
    eca: KURALLAR.map((k) => ({ id: k.id, acik: t.aktif(k.id), olay: t.metin(k, "olay"), kosul: t.metin(k, "kosul"), eylem: t.metin(k, "eylem"), parametreler: d.kurallar[k.id].degerler, kaynak: k.kaynak, kanitIdleri: k.onler })),
    uyarlama: uyarlama_sozlesmesi_default.component_contracts,
    kararModeli: karar_modelleri_default.candidates.find((c) => c.id === d.kararlar.kararModeli) ?? { id: d.kararlar.kararModeli, status: "candidate_only" },
    oncelik: ["iptal ve yetki iptali", "belirsiz d\u0131\u015F etki uzla\u015Ft\u0131rma", "sert b\xFCt\xE7e", "olaya \xF6zel kurtarma"],
    uyarilar: t.uyarilar,
    acikPlanBosluklari: t.kapsam.acikSorunlar.map((s) => ({ id: s.id, baslik: s.baslik })),
    roller: CODEX_ROLLERI,
    skills: SKILLER,
    mcp: MCP_SUNUCULARI,
    teknolojiler: t.teknolojiler,
    diyagramlar: tumDiyagramlar(d, t),
    belgeler: BELGELER.map((b2) => ({ yol: b2.yol, icerik: belgeIcerigi(b2, d) })),
    kanit: kanitlar_default.kayitlar.map((r) => ({ id: r.id, grup: r.grup, yol: r.kaynak, sha256: r.sha256, pointer: r.pointer })),
    kaynakManifesti: kanitlar_default.dosyalar.map((f) => ({ yol: f.yol, sha256: f.sha256 })),
    simulasyonlar: simulasyonGecmisi(d),
    qualification: "not_run",
    uygulanmisOnlemSayisi: 0,
    acikSorular: ["Ger\xE7ek repo / alpha hedefi ve proje profili", "Ara\xE7 s\xFCr\xFCmleri ve adapt\xF6r uygunluk deneyleri", "Ba\u011F\u0131ms\u0131z oracle ve alan kabul verisi", "\xD6l\xE7\xFClm\xFC\u015F kaynak ve insan \xE7\u0131kt\u0131 inceleme kapasitesi"]
  };
}

